from moler.exceptions import ParsingDone, CommandFailure
from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.cmd.commandtextualgeneric import CommandTextualGeneric


class Uexgate(GenericUnixCommand):

    def __init__(self, connection, platform='rtg', prompt=None, newline_chars=None, runner=None):
        """
        :param connection: moler connection to device
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Uexgate, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.platform = platform
        self._re_expected_prompt = CommandTextualGeneric._calculate_prompt("UExGate>")

    def is_failure_indication(self, line, is_full_line):
        """
        Method to detect if passed line contains part indicating failure of command
        :param line: Line from command output on device
        :return: Match object if find regex in line, None otherwise.
        """
        if "command not found" in line:
            return True
        return None

    def build_command_string(self):
        """
        Builds command string from parameters passed to object.
        :return: String representation of command to send over connection to device.
        """
        return "/opt/{}/bin/uexgate".format(self.platform)

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.
        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._is_already_started(line)
            except ParsingDone:
                pass
        try:
            self._is_target_prompt(line)
        except ParsingDone:
            pass

        super(Uexgate, self).on_new_line(line, is_full_line)

    def _is_target_prompt(self, line):
        """
        Checks target prompt.
        :param line: Line to process
        :return: None
        """
        if self._regex_helper.search_compiled(self._re_expected_prompt, line):
            if not self.done():
                self.set_result({})
                raise ParsingDone

    def _is_already_started(self, line):
        """
        Parse info about uex node being already in use.
        :param line: Line from device.
        :return: None
        """
        if "Protocol 'inet_tcp': the name uex@127.0.0.1 seems to be in use by another Erlang node" in line:
            self.set_exception(CommandFailure(self, "UEx app is already started"))
            raise ParsingDone


class Exit(GenericUnixCommand):

    def __init__(self, connection, platform='rtg', prompt=None, newline_chars=None, runner=None):
        """
        :param connection: moler connection to device
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Exit, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.platform = platform
        self._re_expected_prompt = CommandTextualGeneric._calculate_prompt(prompt)

    def is_failure_indication(self, line, is_full_line):
        """
        Method to detect if passed line contains part indicating failure of command
        :param line: Line from command output on device
        :return: Match object if find regex in line, None otherwise.
        """
        if "command not found" in line:
            return True
        return None

    def build_command_string(self):
        """
        Builds command string from parameters passed to object.
        :return: String representation of command to send over connection to device.
        """
        return "exit"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.
        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        try:
            self._is_target_prompt(line)
        except ParsingDone:
            pass

        super(Exit, self).on_new_line(line, is_full_line)

    def _is_target_prompt(self, line):
        """
        Checks target prompt.
        :param line: Line to process
        :return: None
        """
        if self._regex_helper.search_compiled(self._re_expected_prompt, line):
            if not self.done():
                self.set_result({})
                raise ParsingDone
